/* @socom-skeleton body Create__Q23zdb6CModelFRQ23zdb9CSaveLoadPQ23zdb9CAssetLib */
namespace zdb {
CModel* CModel::Create(CSaveLoad& sload, CAssetLib* library)
	{
		CModel* model = new CModel(NULL);

		if (library)
			library->AddModel(model);

		if (model->Read(sload))
			return model;

		if (library)
		{
			auto target = std::find(
				library->m_models.begin(),
				library->m_models.end(),
				model);

			library->m_models.erase(target);
		}

		return model;
	}
}

/* @socom-skeleton body Read__Q23zdb6CModelFRQ23zdb9CSaveLoad */
namespace zdb {
bool CModel::Read(CSaveLoad& sload)
	{
		tag_NODE_PARAMS nparams;

		if (zar::CKey* modelkey = sload.m_zfile.GetOpenKey())
		{
			InitNodeParams(this);
			
			sload.m_zfile.Fetch("nparams", &nparams, sizeof(tag_NODE_PARAMS));
			sload.m_zfile.Fetch("regionmask", &m_region_mask, sizeof(u32));

			m_matrix = nparams.m_matrix;
			m_bbox.m_min = nparams.m_bbox.m_min;
			m_bbox.m_max = nparams.m_bbox.m_max;
			m_type = nparams.m_type;
			m_active = nparams.m_active;

			CNode::Read(sload);
			SetName(modelkey->GetName());
		}

		return true;
	}
}

/* @socom-skeleton body Read__Q23zdb5CNodeFRQ23zdb9CSaveLoadPQ23zdb5CNode */
/* @socom-skeleton body Read__Q23zdb5CNodeFRQ23zdb9CSaveLoadPQ23zdb5CNode */
/* port: file-local helper, not an ELF function - 0x223e40 / 0x223618 copy the node-params
   flag word (+0x5c, the 32 bitfields after m_type) as one word */
static inline void ReadCopyNodeFlags(zdb::tag_NODE_PARAMS* dst, const zdb::tag_NODE_PARAMS* src)
{
	memcpy(reinterpret_cast<char*>(&dst->m_type) + sizeof(dst->m_type),
		reinterpret_cast<const char*>(&src->m_type) + sizeof(src->m_type), sizeof(u32));
}

#ifdef SOCOM_PORT
unsigned socom_port_node_reads[12]; /* port: boot trace - nodes read by type 0..9, [10] instances made, [11] version-0 nodes */
#endif

namespace zdb {
CNode* CNode::Read(CSaveLoad& sload, CNode* parent)
	{
		/* 0x223c30: a node without a "NodeType" key (version 1) carries its params: types
		   1/5 make a CNode, 8 a CLight, 9 a CLensFlare - each takes the params and reads
		   its data, then joins `parent` - and type 2 is an instance of a model (it joins
		   `parent`, or the world without one). A node with "NodeType" (version 0) is a
		   plain CNode that reads itself. Was inverted (a found "NodeType" took the params
		   path), and the params were copied from the new node instead of to it. ELF quirk
		   kept: an instance is not returned (NULL). */
		u32 nodetype = 0;
		u32 regionmask = 0;
		CNode* node = NULL;
		bool instance = false;

		if (!sload.m_zfile.Fetch("NodeType", (s32*)&nodetype))
		{
			sload.m_version = 1;

			tag_NODE_PARAMS nparams;
			sceVu0UnitMatrix(nparams.m_matrix.m_matrix);
			nparams.m_facade = 0;
			InitNodeParams(&nparams, NULL);
			sload.m_zfile.Fetch("nparams", &nparams, sizeof(tag_NODE_PARAMS));
			sload.m_zfile.Fetch("regionmask", &regionmask, sizeof(u32));

#ifdef SOCOM_PORT
			socom_port_node_reads[nparams.m_type < 10 ? nparams.m_type : 0]++;
#endif
			switch (nparams.m_type)
			{
			case 9:
				node = new CLensFlare();
				break;
			case 8:
				node = new CLight();
				break;
			case 1:
			case 5:
				node = new CNode();
				break;
			case 2:
				instance = true;
				break;
			}

			if (instance)
			{
				CNode* inst = CreateInstance(sload);

				if (inst == NULL)
					return node;
#ifdef SOCOM_PORT
				socom_port_node_reads[10]++;
#endif

				if (parent != NULL)
					parent->AddChild(inst);
				else
					CWorld::m_world->AddChild(inst);

				return node;
			}

			if (node == NULL)
				return NULL;

			sceVu0CopyMatrix(node->m_matrix.m_matrix, nparams.m_matrix.m_matrix);
			node->m_bbox.m_min = nparams.m_bbox.m_min;
			node->m_bbox.m_max = nparams.m_bbox.m_max;
			node->m_type = nparams.m_type;
			ReadCopyNodeFlags(node, &nparams);
			node->m_region_mask = regionmask;

			if (node->Read(sload))
			{
				if (parent != NULL)
					parent->AddChild(node);
			}
			else
			{
				delete node;
				node = NULL;
			}

			return node;
		}

		sload.m_version = 0;
#ifdef SOCOM_PORT
		socom_port_node_reads[11]++;
#endif
		zar::CKey* key = sload.m_zfile.GetOpenKey();
		sload.m_zfile.OpenKey(key);
		sload.m_zfile.Fetch("NodeType", (s32*)&nodetype);
		node = new CNode();

		if (node != NULL && node->Read(sload) && parent != NULL)
			parent->AddChild(node);

		sload.m_zfile.CloseKey(key);
		return node;
	}
}

/* @socom-skeleton body ReadDataBegin__Q23zdb5CNodeFRQ23zdb9CSaveLoad */
namespace zdb {
bool CNode::ReadDataBegin(CSaveLoad& sload)
	{
		zar::CKey* openkey = sload.m_zfile.GetOpenKey();
		SetName(openkey->GetName());
		zar::CKey* visualskey = sload.m_zfile.OpenKey("visuals");

		// If the node has visuals
		if (visualskey)
		{
			ReserveVisuals(visualskey->GetSize());

			/* 0x223b00: the loop steps to the next key (it never advanced here before). */
			for (auto it = visualskey->begin(); it != visualskey->end(); ++it)
			{
				zar::CKey* key = sload.m_zfile.OpenKey(*it);
				
				if (key)
				{
					CVisual* vis = CVisual::Create(sload.m_zfile);

					if (vis)
					{
						AddVisual(vis);
					}

					sload.m_zfile.CloseKey(key);
				}
			}

			sload.m_zfile.CloseKey(visualskey);
		}

		zar::CKey* dikey = sload.m_zfile.OpenKey("di");

		if (dikey)
		{
			ReserveDI(dikey->GetSize());

			for (auto it = dikey->begin(); it != dikey->end(); ++it) /* 0x223bd0 */
			{
				zar::CKey* key = sload.m_zfile.OpenKey(*it);

				if (key)
				{
					CDI* di = CDI::Create(sload);

					if (di)
					{
						AddDI(di);
					}

					sload.m_zfile.CloseKey(key);
				}
			}

			sload.m_zfile.CloseKey(dikey);
		}

		return false;
	}
}

/* @socom-skeleton body Read__Q23zdb5CNodeFRQ23zdb9CSaveLoad */
namespace zdb {
bool CNode::Read(CSaveLoad& sload)
	{
		if (sload.m_version == 1)
		{
			ReadDataBegin(sload);

			if (zar::CKey* children = sload.m_zfile.OpenKey("children"))
			{
				ReserveChildren(children->GetSize());

				for (auto i = children->begin(); i != children->end(); ++i)
				{
					zar::CKey* key = sload.m_zfile.OpenKey(*i);
					Read(sload, this);
					sload.m_zfile.CloseKey(key);
				}

				sload.m_zfile.CloseKey(children);
			}
		}
		else
		{
			zar::CKey* openkey = sload.m_zfile.GetOpenKey();
			SetName(openkey->GetName());
			sload.m_zfile.Fetch("matrix", &m_matrix, sizeof(CMatrix));
			sload.m_zfile.Fetch("bbox", &m_bbox, sizeof(CBBox));

			// If the node has visuals
			if (zar::CKey* visuals = sload.m_zfile.OpenKey("visuals"))
			{
				ReserveVisuals(visuals->GetSize());

				for (auto i = visuals->begin(); i != visuals->end(); ++i)
				{
					if (zar::CKey* key = sload.m_zfile.OpenKey(*i))
					{
						CVisual* vis = CVisual::Create(sload.m_zfile);
						AddVisual(vis);
						sload.m_zfile.CloseKey(key);
					}
				}

				sload.m_zfile.CloseKey(visuals);
			}

			// If the node has collision data
			if (zar::CKey* di = sload.m_zfile.OpenKey("di"))
			{
				ReserveDI(di->GetSize());

				for (auto i = di->begin(); i != di->end(); ++i)
				{
					if (zar::CKey* key = sload.m_zfile.OpenKey(*i))
					{
						CDI* di = CDI::Create(sload);
						AddDI(di);
						sload.m_zfile.CloseKey(key);
					}
				}

				sload.m_zfile.CloseKey(di);
			}

			/* 0x223660: each branch reads the children once (they were read twice for version 1). */
			if (zar::CKey* children = sload.m_zfile.OpenKey("children"))
			{
				ReserveChildren(children->GetSize());

				for (auto i = children->begin(); i != children->end(); ++i)
				{
					zar::CKey* key = sload.m_zfile.OpenKey(*i);
					Read(sload, this);
					sload.m_zfile.CloseKey(key);
				}

				sload.m_zfile.CloseKey(children);
			}
		}

		return true;
	}
}

/* @socom-skeleton body CreateInstance__Q23zdb5CNodeFRQ23zdb9CSaveLoad */
/* @socom-skeleton body CreateInstance__Q23zdb5CNodeFRQ23zdb9CSaveLoad */
namespace zdb {
CNode* CNode::CreateInstance(CSaveLoad& sload)
	{
		/* 0x2234c0: an instance node of the named model, with the stored matrix, bbox,
		   flags and region mask, typed 2 (instance), then its own visuals/DI data. Was:
		   no flags or region mask, the read type kept, and the name freed only when NULL. */
		tag_NODE_PARAMS nparams;
		u32 regionmask = 0;
		char* modelname = NULL;
		CWorld* world = CWorld::m_world;

		sceVu0UnitMatrix(nparams.m_matrix.m_matrix);
		nparams.m_facade = 0;

		if (world == NULL)
			return NULL;

		InitNodeParams(&nparams, NULL);

		sload.m_zfile.Fetch("model_name", &modelname);
		sload.m_zfile.Fetch("nparams", &nparams, sizeof(tag_NODE_PARAMS));
		sload.m_zfile.Fetch("regionmask", &regionmask, sizeof(u32));

		if (modelname == NULL)
			return NULL;

		CModel* model = CWorld::GetModel(modelname);

		if (modelname != NULL)
			zfree(modelname);

		modelname = NULL;

		if (model == NULL)
			return NULL;

		CNode* node = CreateInstance(model, NULL, NULL);
		sceVu0CopyMatrix(node->m_matrix.m_matrix, nparams.m_matrix.m_matrix);
		node->m_bbox.m_min = nparams.m_bbox.m_min;
		node->m_bbox.m_max = nparams.m_bbox.m_max;
		node->m_type = nparams.m_type;
		ReadCopyNodeFlags(node, &nparams);
		node->m_region_mask = regionmask;
		node->m_type = 2;
		node->ReadDataBegin(sload);
		return node;
	}
}

